      self.run(m, SKIP_ARM_TICKS);
      const skipped = m.skipRoundEnd();
      m.step();
      const next = m.phase === 'waiting';
      log.countdown.length = 0;
      m.startRound();
      let ticks2 = 0;
      while (m.phase === 'countdown' && ticks2 < 400) { m.step(); ticks2++; }
      log.stop();
      const round2 = log.countdown.map((e) => e.n).join();
      m.dispose();
