      const ok = first >= ROUND_BANNER_TICKS && round1 === '3,2,1' && round2 === '2,1' && ticks2 < ticks && !early && skipped && next && slowAtKo;
      return ok ? true : JSON.stringify({ first, round1, round2, ticks, ticks2, early, skipped, next, slowAtKo });
