        const a = MOVE_STYLE_IDS[i], b = MOVE_STYLE_IDS[j];
        const cross = maxGap(poses[a][0], poses[b][0]), kick = maxGap(poses[a][1], poses[b][1]);
        if (cross < 0.25) problems.push(a + ' / ' + b + ' cross ' + cross.toFixed(2));
