          m.controllers[0] = new AIController(m.fighters[0].profile, 'hard'); m.controllers[1] = new AIController(m.fighters[1].profile, 'hard');
          for (let t = 0; t < 4800 && !used && m.phase !== 'matchEnd'; t++) { m.step(); if (m.phase === 'waiting') m.startRound(); }
          off();
          if (used) seeds++;
