          for (let i = 1; i < parts.length; i++) if (Math.abs(parts[i][1]) <= 1 && Math.abs(parts[i][3]) <= 1) spots.push([host.x + parts[i][1] * host.hx, host.z + parts[i][3] * host.hz]);
