      if (done !== true) return done;
      if (!host.waiting.some((entry) => entry[1] === 'Waiting for P3...') || !fourth.waiting.some((entry) => entry[1] === 'Waiting for P3...')) problems.push('the waiting text ' + JSON.stringify(host.waiting.slice(0, 2)));
