        if (version >= 7 && ((x >= size - 11 && y < 6) || (y >= size - 11 && x < 6))) return true;
        return centres.some((cy, i) => centres.some((cx, j) => !(i === 0 && j === 0) && !(i === 0 && j === count - 1) && !(i === count - 1 && j === 0) && Math.abs(x - cx) <= 2 && Math.abs(y - cy) <= 2));
